#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n;cin>>n;vector<int>a(n),ones,neg;for(int i=0;i<n;i++){cin>>a[i];if(a[i]==1)ones.push_back(i);if(a[i]==-1)neg.push_back(i);}int bestL=-1,bestR=-1,bestLen=0;auto update=[&](int l,int r){if(l<0||r<0||l>r)return;if(r-l+1>bestLen){bestLen=r-l+1;bestL=l;bestR=r;}};if(!ones.empty()){for(int i=0;i+1<(int)ones.size();i++)update(ones[i],ones[i+1]);for(int i:neg)if(i<ones.front()){update(i,ones.front());break;}for(int i=(int)neg.size()-1;i>=0;i--)if(neg[i]>ones.back()){update(ones.back(),neg[i]);break;}if(bestLen==0)bestL=bestR=ones[0];}else{if((int)neg.size()>=2)update(neg.front(),neg.back());else if((int)neg.size()==1)bestL=bestR=neg[0];}for(int &x:a)if(x==-1)x=0;if(bestL!=-1){a[bestL]=1;a[bestR]=1;}for(int i=0;i<n;i++)cout<<a[i]<<(i+1==n?'\n':' ');}}
